from urllib.parse import urlencode
from .profiles import DEFAULT_HEADERS, DEFAULT_QUERY

def headers(overrides):
    result = dict(DEFAULT_HEADERS)
    for key, value in (overrides or {}).items():
        for old in list(result):
            if old.lower() == key.lower():
                del result[old]
        if value is not None:
            result[key] = value
    return result

def query(overrides):
    merged = dict(DEFAULT_QUERY)
    for key, value in (overrides or {}).items():
        if value is None:
            merged.pop(key, None)
        else:
            merged[key] = value
    return urlencode(merged, doseq=True)

