from urllib.parse import urlsplit

def retryable(method, status):
    return method.upper() in ('GET', 'HEAD') and status in (429, 503)

def origin(url):
    p = urlsplit(url)
    return (p.scheme.lower(), p.hostname, p.port or {'http':80,'https':443}.get(p.scheme.lower()))

def redirect_headers(headers, source, target):
    if origin(source) == origin(target):
        return dict(headers)
    return {k:v for k,v in headers.items() if k.lower() not in ('authorization', 'cookie')}

