def position(body):
    return body.tell() if hasattr(body, 'tell') else None

def read(body):
    return body.read() if hasattr(body, 'read') else body

def rewind(body, initial):
    if initial is not None:
        body.seek(initial)

def release(body):
    pass  # The caller owns the supplied stream.

