from . import policy, body as bodies

class Transport:
    def __init__(self, adapter, sleeper=lambda seconds: None):
        self.adapter = adapter
        self.sleeper = sleeper

    def send(self, method, url, *, prepared, profile, lane, timeout=None, body=None, trace=False):
        headers = dict(prepared["headers"])
        if trace and lane == "alpha":
            headers["X-Lane"] = lane
        limit = profile["max_attempts"]
        effective_timeout = profile["timeout"] if timeout is None else timeout
        initial = bodies.position(body)
        try:
            for attempt in range(limit):
                if attempt:
                    bodies.rewind(body, initial)
                response = self.adapter.request(method, url, headers=dict(headers), query=prepared["query"], timeout=effective_timeout, body=bodies.read(body))
                if response.status in (301, 302, 307, 308) and response.location:
                    headers = policy.redirect_headers(headers, url, response.location)
                    url = response.location
                    continue
                if policy.retryable(method, response.status) and attempt + 1 < limit:
                    value = next((v for k,v in response.headers.items() if k.lower() == 'retry-after'), None)
                    if response.status == 429 and isinstance(value, str) and value.isascii() and value.isdecimal() and 0 <= int(value) <= 8:
                        self.sleeper(int(value))
                    continue
                return response
            return response
        finally:
            bodies.release(body)
